-- 613: Original BrillaPrep Cambridge IGCSE Physics (0625) Electricity and Magnetism practice questions (part 2 of 2) (batch igcse-physics-sprint3-001).
-- Curriculum-aligned practice content; not official Cambridge International, WAEC or NSMQ material.
PRAGMA foreign_keys = ON;
CREATE TABLE _migration_613_expected (id TEXT PRIMARY KEY, topic_id TEXT, subject_id TEXT, exam_type_id TEXT, paper_type_id TEXT, past_paper_id TEXT, question_text TEXT, question_type TEXT, round_type TEXT, options TEXT, correct_answer TEXT, explanation TEXT, difficulty TEXT, points INTEGER, marks INTEGER, time_limit INTEGER, question_number INTEGER, section TEXT, is_compulsory INTEGER, image_url TEXT, syllabus_topic_id TEXT, command_word TEXT, assessment_objective TEXT, source_paper_code TEXT, source_question_number TEXT, exam_board_id TEXT);
INSERT INTO _migration_613_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_igphy_electricity_s3_009', 'topic_igcse_physics_electricity', 'subj_igcse_physics', 'igcse', NULL, NULL, 'An electric kettle rated at 3.0 kW operates on a 230 V mains supply. Calculate the current drawn and select the most suitable fuse rating.', 'multiple_choice', NULL, '["A. 3 A fuse (current ≈ 13 A)","B. 13 A fuse (current ≈ 13 A)","C. 5 A fuse (current ≈ 13 A)","D. 30 A fuse (current ≈ 0.08 A)"]', 'B', 'The current is I = P ÷ V = 3,000 ÷ 230 ≈ 13.0 A. A fuse should be rated just above the normal operating current, so a 13 A fuse is correct. (3 A and 5 A fuses would melt during normal use; 0.08 A comes from inverting the relation to V/P.) Therefore the correct answer is B: 13 A fuse (current ≈ 13 A).', 'hard', '4', '1', '120', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO3', NULL, NULL, 'board_cambridge'),
('q_igphy_electricity_s3_010', 'topic_igcse_physics_electricity', 'subj_igcse_physics', 'igcse', NULL, NULL, 'A student investigates how the current through a fixed resistor varies with the potential difference across it.', 'structured', NULL, NULL, '(a) A d.c. supply or battery connected in series with an ammeter, a variable resistor (rheostat) and the fixed resistor; a voltmeter is connected in parallel across the fixed resistor to measure the potential difference. (b) The current is directly proportional to the potential difference across the resistor, provided the temperature and other physical conditions remain constant (V = IR with R constant). (c) R = V ÷ I = 6.0 ÷ 0.40 = 15 Ω; at 9.0 V the current is I = V ÷ R = 9.0 ÷ 15 = 0.60 A.', '(a) A d.c. supply or battery connected in series with an ammeter, a variable resistor (rheostat) and the fixed resistor; a voltmeter is connected in parallel across the fixed resistor to measure the potential difference. (b) The current is directly proportional to the potential difference across the resistor, provided the temperature and other physical conditions remain constant (V = IR with R constant). (c) R = V ÷ I = 6.0 ÷ 0.40 = 15 Ω; at 9.0 V the current is I = V ÷ R = 9.0 ÷ 15 = 0.60 A.', 'hard', '7', '7', NULL, NULL, NULL, '1', NULL, NULL, 'Describe', 'AO2', NULL, NULL, 'board_cambridge');
CREATE TABLE _migration_613_expected_parts (id TEXT PRIMARY KEY, question_id TEXT NOT NULL, part_label TEXT NOT NULL, part_text TEXT NOT NULL, marks INTEGER NOT NULL, correct_answer TEXT NOT NULL, display_order INTEGER NOT NULL);
INSERT INTO _migration_613_expected_parts (id, question_id, part_label, part_text, marks, correct_answer, display_order) VALUES ('sqp_q_igphy_electricity_s3_010_a', 'q_igphy_electricity_s3_010', 'a', 'Describe the circuit the student should use, naming the meters and stating where each is connected.', '2', 'A d.c. supply or battery connected in series with an ammeter, a variable resistor (rheostat) and the fixed resistor; a voltmeter is connected in parallel across the fixed resistor to measure the potential difference.', '1'),
('sqp_q_igphy_electricity_s3_010_b', 'q_igphy_electricity_s3_010', 'b', 'State the relationship between the current and the potential difference for a resistor that obeys Ohm’s law.', '2', 'The current is directly proportional to the potential difference across the resistor, provided the temperature and other physical conditions remain constant (V = IR with R constant).', '2'),
('sqp_q_igphy_electricity_s3_010_c', 'q_igphy_electricity_s3_010', 'c', 'The student records a current of 0.40 A when the potential difference is 6.0 V. Calculate the resistance of the resistor, and the current when the potential difference is increased to 9.0 V.', '3', 'R = V ÷ I = 6.0 ÷ 0.40 = 15 Ω; at 9.0 V the current is I = V ÷ R = 9.0 ÷ 15 = 0.60 A.', '3');
CREATE TABLE IF NOT EXISTS _migration_613_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_613_guard;
INSERT INTO _migration_613_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_613_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_613_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'igcse-physics-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Physics (0625) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-physics-0625/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) AND NOT EXISTS (SELECT 1 FROM _migration_613_expected_parts p JOIN structured_question_parts sp ON sp.id = p.id WHERE NOT (sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_613_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) SELECT p.id, p.question_id, p.part_label, p.part_text, p.marks, p.correct_answer, NULL, 'text', p.display_order FROM _migration_613_expected_parts p WHERE NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = p.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'igcse-physics-sprint3-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Physics (0625) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.', 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-physics-0625/', 0, 1 FROM _migration_613_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
DELETE FROM _migration_613_guard;
INSERT INTO _migration_613_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_613_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 2 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_613_expected e ON e.id = r.question_id WHERE r.batch_id IS 'igcse-physics-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Physics (0625) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-physics-0625/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 2 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_613_expected e ON e.id = q.id) = 2 AND (SELECT COUNT(*) FROM structured_question_parts sp JOIN _migration_613_expected_parts p ON p.id = sp.id AND sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order) = 3 THEN 1 ELSE 0 END;
DROP TABLE _migration_613_guard;
